def load_config(config_path: Optional[str] = None, no_config: bool = False) -> Config:
    """Load configuration from file"""
    cfg = Config()
    rule_cfg = default_rule_config()

    if no_config:
        cfg.rules = rule_cfg
        return cfg

    config_file = None
    if config_path:
        config_file = Path(config_path)
    else:
        # Search for config file
        for name in [".rumdl.toml", "rumdl.toml"]:
            p = Path(name)
            if p.exists():
                config_file = p
                break
        if not config_file:
            # Check pyproject.toml
            pp = Path("pyproject.toml")
            if pp.exists():
                config_file = pp

    if config_file and config_file.exists():
        try:
            import tomllib
        except ImportError:
            try:
                import tomli as tomllib
            except ImportError:
                # Use our own minimal TOML parser
                tomllib = None

        if tomllib:
            with open(config_file, 'rb') as f:
                data = tomllib.load(f)
        else:
            data = parse_toml_simple(config_file)

        # Check if it's pyproject.toml
        if str(config_file).endswith('pyproject.toml'):
            data = data.get('tool', {}).get('rumdl', {})

        # Parse global section
        global_cfg = data.get('global', {})
        # Also accept top-level keys for pyproject.toml style
        if not global_cfg and any(k in data for k in ['enable', 'disable', 'exclude']):
            global_cfg = data

        if 'enable' in global_cfg:
            cfg.enable = [r.upper() for r in global_cfg['enable']]
        if 'disable' in global_cfg:
            cfg.disable = [r.upper() for r in global_cfg['disable']]
        if 'exclude' in global_cfg:
            cfg.exclude = global_cfg['exclude']
        if 'include' in global_cfg:
            cfg.include = global_cfg['include']
        if 'respect-gitignore' in global_cfg or 'respect_gitignore' in global_cfg:
            cfg.respect_gitignore = global_cfg.get('respect-gitignore', global_cfg.get('respect_gitignore', True))
        if 'flavor' in global_cfg:
            cfg.flavor = global_cfg['flavor']

        # Parse per-file-ignores
        pfi = data.get('per-file-ignores', data.get('per_file_ignores', {}))
        cfg.per_file_ignores = {k: [r.upper() for r in v] for k, v in pfi.items()}

        # Parse per-file-flavor
        pff = data.get('per-file-flavor', data.get('per_file_flavor', {}))
        cfg.per_file_flavor = pff

        # Parse rule-specific configs
        for rule_id in ALL_RULES:
            if rule_id in data:
                rule_data = data[rule_id]
                if isinstance(rule_data, dict):
                    if rule_id not in rule_cfg:
                        rule_cfg[rule_id] = {}
                    rule_cfg[rule_id].update(rule_data)

    cfg.rules = rule_cfg
    return cfg


def parse_toml_simple(config_file) -> dict:
    """Simple TOML parser for basic configs"""
    try:
        # Try Python 3.11+ tomllib
        import tomllib
        with open(config_file, 'rb') as f:
            return tomllib.load(f)
    except ImportError:
        pass

    # Manual parsing for basic TOML
    result = {}
    current_section = result
    current_path = []

    with open(config_file, 'r') as f:
        for line in f:
            line = line.rstrip('\n')
            stripped = line.strip()

            if not stripped or stripped.startswith('#'):
                continue

            # Section header
            if stripped.startswith('[') and stripped.endswith(']'):
                section_name = stripped[1:-1].strip()
                parts = section_name.split('.')
                current_path = parts
                d = result
                for p in parts:
                    if p not in d:
                        d[p] = {}
                    d = d[p]
                current_section = d
                continue

            # Key-value pair
            if '=' in line:
                key, _, value = line.partition('=')
                key = key.strip()
                value = value.strip()

                # Handle inline comments
                if '#' in value:
                    # Simple: remove after #
                    value = value[:value.index('#')].strip()

                # Parse value
                parsed = parse_toml_value(value)
                current_section[key] = parsed

    return result


def parse_toml_value(value: str):
    """Parse a simple TOML value"""
    value = value.strip()
    if not value:
        return None
    if value.startswith('"') and value.endswith('"'):
        return value[1:-1]
    if value.startswith("'") and value.endswith("'"):
        return value[1:-1]
    if value.lower() == 'true':
        return True
    if value.lower() == 'false':
        return False
    try:
        if '.' in value:
            return float(value)
        return int(value)
    except ValueError:
        pass
    if value.startswith('[') and value.endswith(']'):
        inner = value[1:-1].strip()
        if not inner:
            return []
        items = []
        for item in inner.split(','):
            item = item.strip()
            if item:
                items.append(parse_toml_value(item))
        return items
    return value


