def is_rule_disabled(rule: str, line_idx: int, line_disabled_map: dict) -> bool:
    """Check if a rule is disabled for a given line"""
    disabled = line_disabled_map.get(line_idx, set())
    return rule in disabled


def make_violation(file: str, line: int, col: int, rule: str, message: str,
                   fixable: bool = False, fix_start: int = -1, fix_end: int = -1,
                   fix_replacement: str = "") -> Violation:
    severity = RULE_SEVERITY.get(rule, "warning")
    v = Violation(file=file, line=line, column=col, rule=rule, message=message,
                  severity=severity, fixable=fixable,
                  fix_start=fix_start, fix_end=fix_end,
                  fix_replacement=fix_replacement)
    return v


def heading_to_anchor(heading_text: str) -> str:
    """Convert heading text to GitHub-style anchor"""
    # GitHub anchor generation
    anchor = heading_text.lower()
    # Remove non-alphanumeric characters except spaces and hyphens
    anchor = re.sub(r'[^\w\s-]', '', anchor, flags=re.UNICODE)
    # Replace spaces with hyphens
    anchor = re.sub(r'\s+', '-', anchor.strip())
    # Remove multiple hyphens
    anchor = re.sub(r'-+', '-', anchor)
    return anchor


def is_blank_line(line: str) -> bool:
    return line.strip() == ''


def is_atx_heading(line: str) -> Tuple[Optional[int], Optional[str]]:
    """Returns (level, text) or (None, None)"""
    m = re.match(r'^(#{1,6})\s+(.*?)(\s+#+\s*)?$', line)
    if m:
        level = len(m.group(1))
        text = m.group(2).strip()
        # Remove trailing hashes (closed atx)
        trailing = m.group(3)
        if trailing:
            text = m.group(2).rstrip()
        return level, text
    # No space after hash
    m2 = re.match(r'^(#{1,6})(\S.*)?$', line)
    if m2 and not line.startswith('#' * (len(m2.group(1)) + 1)):
        # It's an ATX heading without space (MD018)
