def get_headings(lines, code_blocks, frontmatter_end=-1):
    """Extract all headings from document"""
    headings = []
    setext_pending = None  # (line_idx, text)

    for i, line in enumerate(lines):
        # Skip frontmatter
        if frontmatter_end >= 0 and i <= frontmatter_end:
            continue

        if is_in_code_block(i, code_blocks):
            setext_pending = None
            continue

        # Check for setext heading underline
        if setext_pending is not None:
            prev_text = setext_pending[1]
            stripped = line.strip()
            if re.match(r'^=+\s*$', stripped) and stripped:
                headings.append((setext_pending[0], 1, prev_text, 'setext'))
                setext_pending = None
                continue
            elif re.match(r'^-+\s*$', stripped) and stripped and len(stripped) >= 2:
                headings.append((setext_pending[0], 2, prev_text, 'setext'))
                setext_pending = None
                continue
            else:
                setext_pending = None

        # ATX heading
        m = re.match(r'^(#{1,6})(\s+)(.*?)(\s+#+\s*)?$', line)
        if m:
            level = len(m.group(1))
            text = m.group(3).strip()
            trailing = m.group(4)
            if trailing:
                style = 'atx_closed'
            else:
                style = 'atx'
            headings.append((i, level, text, style))
            setext_pending = None
            continue

        # Check for ATX without space (invalid but still a heading structurally)
        m2 = re.match(r'^(#{1,6})(\S.*)$', line)
        if m2:
            # This is MD018 but we still need to recognize it as a heading
            level = len(m2.group(1))
            text = m2.group(2).strip()
            headings.append((i, level, text, 'atx_nospace'))
            setext_pending = None
            continue

        # Potential setext heading (next line might be === or ---)
        if line.strip() and not is_blank_line(line) and not is_list_item(line)[0]:
            setext_pending = (i, line.strip())
        else:
            setext_pending = None

    return headings


def get_block_quote_lines(lines, code_blocks, frontmatter_end=-1):
    """Find all lines that are part of block quotes"""
    bq_lines = []
    for i, line in enumerate(lines):
        if frontmatter_end >= 0 and i <= frontmatter_end:
            continue
        if is_in_code_block(i, code_blocks):
            continue
        if re.match(r'^\s*>', line):
            bq_lines.append(i)
    return bq_lines


def get_list_items(lines, code_blocks, frontmatter_end=-1):
    """Extract all list items"""
    items = []
    for i, line in enumerate(lines):
        if frontmatter_end >= 0 and i <= frontmatter_end:
            continue
        if is_in_code_block(i, code_blocks):
            continue
        is_list, marker, indent = is_list_item(line)
        if is_list:
            items.append((i, indent, marker, marker == 'ol'))
    return items


def get_link_definitions(lines, code_blocks, frontmatter_end=-1):
    """Extract all link reference definitions"""
    defs = {}
    for i, line in enumerate(lines):
        if frontmatter_end >= 0 and i <= frontmatter_end:
            continue
        if is_in_code_block(i, code_blocks):
            continue
        m = re.match(r'^\[([^\]]+)\]:\s*(\S+)(?:\s+".*?")?', line)
        if m:
            label = m.group(1).lower()
            url = m.group(2)
            defs[label] = (url, i)
    return defs


def get_footnote_defs_and_refs(lines, code_blocks, frontmatter_end=-1):
    """Extract footnote definitions and references"""
    defs = {}  # label -> line_idx
    refs = []  # (label, line_idx)

    for i, line in enumerate(lines):
        if frontmatter_end >= 0 and i <= frontmatter_end:
            continue
        if is_in_code_block(i, code_blocks):
            continue

        # Footnote definition: [^label]:
        m = re.match(r'^\[\^([^\]]+)\]:\s*(.*)', line)
        if m:
            label = m.group(1)
            content = m.group(2).strip()
            defs[label] = (i, content)
            continue

        # Footnote references in text: [^label]
        for ref_m in re.finditer(r'\[\^([^\]]+)\](?!:)', line):
            refs.append((ref_m.group(1), i))

    return defs, refs


