    if not should_run('MD047', len(lines) - 1):
        return violations

    if not content.endswith('\n'):
        last_line_idx = len(lines) - 1
        col = len(lines[-1]) + 1 if lines else 1
        v = make_violation(ctx['filepath'], last_line_idx + 1, col, 'MD047',
