    cfg = ctx['config'].get('MD048', {})
    style = cfg.get('style', 'consistent')

    fenced_blocks = [(s, e, l, f) for s, e, l, f in code_blocks if f]

    if not fenced_blocks:
        return violations

    # Determine fence char for each block
    block_styles = []
    for start, end, lang, is_fenced in fenced_blocks:
        if start < len(lines):
