def apply_fixes(content: str, violations: List[Violation]) -> str:
    """Apply fixes for all fixable violations"""
    # Sort violations by position (reverse order for stable offsets)
    fixable = [v for v in violations if v.fixable and v.fix_start >= 0]
    fixable.sort(key=lambda v: v.fix_start, reverse=True)

    result = content
    for v in fixable:
        result = result[:v.fix_start] + v.fix_replacement + result[v.fix_end:]

    return result


