        # Fix code fence style
        m = re.match(r'^(`{3,}|~{3,})(.*)', line)
        if m:
            current_char = m.group(1)[0]
            fence_len = len(m.group(1))
            lang = m.group(2)
            # Determine expected char from message
            if '```' in v.message:
                expected_char = '`'
            else:
                expected_char = '~'
            return expected_char * fence_len + lang

    elif rule == 'MD049':
        # Fix emphasis style
        if '_' in line and '*' not in line or '* instead of _' in v.message:
            # Convert _ to *
            def fix_italic(m):
                return '*' + m.group(1) + '*'
            return re.sub(r'(?<!_)_([^_]+)_(?!_)', fix_italic, line)

    elif rule == 'MD050':
        # Fix strong emphasis style
        if '__' in line and '**' not in line or '** instead of __' in v.message:
            return line.replace('__', '**')
        elif '**' in line and '__' not in line or '__ instead of **' in v.message:
            return line.replace('**', '__')

    elif rule == 'MD053':
        # Remove unused link definition
        if re.match(r'^\[[^\]]+\]:', line):
            return None  # Signal to remove this line

    elif rule == 'MD062':
        # Fix link destination whitespace
        return re.sub(r'\[([^\]]*)\]\(\s*([^)]*?)\s*\)', lambda m: f'[{m.group(1)}]({m.group(2).strip()})', line)

    elif rule == 'MD064':
        # Remove extra consecutive spaces
        def fix_spaces(m):
            return ' '
        # Only in text, not in heading or code
        return re.sub(r'(?<=\S) {2,}(?=\S)', ' ', line)

    elif rule == 'MD069':
        # Remove duplicate list marker
        return re.sub(r'^(\s*)([-*+])\s+\2\s+', r'\1\2 ', line)

    return line


