def apply_fixes(content: str, violations: List[Violation]) -> str:
    """Apply fixes for all fixable violations"""
    # Sort violations by position (reverse order for stable offsets)
    fixable = [v for v in violations if v.fixable and v.fix_start >= 0]
    fixable.sort(key=lambda v: v.fix_start, reverse=True)

    result = content
    for v in fixable:
        result = result[:v.fix_start] + v.fix_replacement + result[v.fix_end:]

    return result


def fix_content(content: str, violations: List[Violation], filepath: str = '') -> str:
    """Apply line-level fixes for violations that need it"""
    lines = content.split('\n')

    # Group violations by line
    by_line = {}
    for v in violations:
        if v.fixable:
            line_idx = v.line - 1
            if line_idx not in by_line:
                by_line[line_idx] = []
            by_line[line_idx].append(v)

    # Apply fixes line by line
    new_lines = list(lines)

    # Re-run fixes on the whole content using rule-specific fixers
    fixed = fix_all(content, violations)

    return fixed


