        if add_before:
            result_lines.append('')
        result_lines.append(line)
        if add_after:
            result_lines.append('')

        i += 1

    # MD047: add final newline
    if md047_fixes:
        result = '\n'.join(result_lines)
        if not result.endswith('\n'):
            result += '\n'
        return result

    # MD012: remove extra blank lines
    if md012_fixes:
        fixed_lines = []
        consecutive_blanks = 0
        for line in result_lines:
            if is_blank_line(line):
