# ============================================================
# OUTPUT FORMATTING
# ============================================================

def format_violations(violations: List[Violation], output_format: str = 'text',
                      show_full_path: bool = False, use_color: bool = True,
                      is_fix_mode: bool = False) -> str:
    """Format violations for output"""

    if output_format == 'json':
        return format_json(violations)
    elif output_format == 'json-lines':
        return format_json_lines(violations)
    elif output_format == 'github':
        return format_github(violations)
    elif output_format == 'gitlab':
        return format_gitlab(violations)
    elif output_format == 'pylint':
        return format_pylint(violations)
    elif output_format == 'azure':
        return format_azure(violations)
    elif output_format == 'sarif':
        return format_sarif(violations)
    elif output_format == 'junit':
        return format_junit(violations)
    elif output_format == 'grouped':
        return format_grouped(violations, use_color)
    elif output_format == 'concise':
        return format_concise(violations, use_color)
    else:
        return format_text(violations, use_color, is_fix_mode)


def format_text(violations: List[Violation], use_color: bool = True, is_fix_mode: bool = False) -> str:
    """Format as text output"""
    lines = []
    for v in violations:
        fixable_str = ' [*]' if v.fixable and not is_fix_mode else (' [fixed]' if is_fix_mode and v.fixable else '')
        if not v.fixable and is_fix_mode:
            fixable_str = ''

        line = f'{v.file}:{v.line}:{v.column}: [{v.rule}] {v.message}{fixable_str}'
        lines.append(line)
    return '\n'.join(lines)


def format_concise(violations: List[Violation], use_color: bool = True) -> str:
    """Format as concise output (no fixable indicator)"""
    lines = []
    for v in violations:
        line = f'{v.file}:{v.line}:{v.column}: [{v.rule}] {v.message}'
        lines.append(line)
    return '\n'.join(lines)


def format_grouped(violations: List[Violation], use_color: bool = True) -> str:
    """Format grouped by file and rule"""
    # Group by file
    by_file = {}
    for v in violations:
        if v.file not in by_file:
            by_file[v.file] = {}
        if v.rule not in by_file[v.file]:
            by_file[v.file][v.rule] = []
        by_file[v.file][v.rule].append(v)

    lines = []
    for filepath, rules in by_file.items():
        lines.append(f'{filepath}:')
        for rule, viols in sorted(rules.items()):
            lines.append(f'  {rule}:')
            for v in viols:
                fixable_str = ' (fixable)' if v.fixable else ''
                lines.append(f'    {v.line}:{v.column} {v.message}{fixable_str}')

    return '\n'.join(lines)


def format_json(violations: List[Violation]) -> str:
    """Format as JSON array"""
    result = []
    for v in violations:
        item = {
            'file': v.file,
            'line': v.line,
            'column': v.column,
            'rule': v.rule,
            'message': v.message,
            'severity': v.severity,
            'fixable': v.fixable,
        }
        if v.fixable and v.fix_start >= 0:
            item['fix'] = {
                'range': {
                    'start': v.fix_start,
                    'end': v.fix_end,
                },
                'replacement': v.fix_replacement,
            }
        result.append(item)
    return json.dumps(result, indent=2)


def format_json_lines(violations: List[Violation]) -> str:
    """Format as JSON lines"""
    lines = []
    for v in violations:
        item = {
            'file': v.file,
            'line': v.line,
            'column': v.column,
            'rule': v.rule,
            'message': v.message,
            'severity': v.severity,
            'fixable': v.fixable,
        }
        lines.append(json.dumps(item))
    return '\n'.join(lines)


def format_github(violations: List[Violation]) -> str:
    """Format as GitHub Actions annotations"""
    lines = []
    for v in violations:
        level = 'error' if v.severity == 'error' else 'warning'
        # Calculate end column - simplified
        end_col = v.column + len(v.message) // 4
        line = f'::{level} file={v.file},line={v.line},col={v.column},endLine={v.line},endColumn={end_col},title={v.rule}::{v.message}'
        lines.append(line)
    return '\n'.join(lines)


def format_gitlab(violations: List[Violation]) -> str:
    """Format as GitLab Code Quality report"""
    result = []
    for v in violations:
        item = {
            'description': v.message,
            'check_name': v.rule,
            'fingerprint': f'{v.file}-{v.line}-{v.column}-{v.rule}',
            'severity': 'minor',
            'location': {
                'path': v.file,
                'lines': {
                    'begin': v.line,
                },
            },
        }
        result.append(item)
    return json.dumps(result, indent=2)


def format_pylint(violations: List[Violation]) -> str:
    """Format as pylint-compatible output"""
    lines = []
    for v in violations:
        line = f'{v.file}:{v.line}:{v.column}: [C{v.rule[2:]}] {v.message}'
        lines.append(line)
    return '\n'.join(lines)


def format_azure(violations: List[Violation]) -> str:
    """Format as Azure DevOps pipeline logging commands"""
    lines = []
    for v in violations:
        level = 'error' if v.severity == 'error' else 'warning'
        line = f'##vso[task.logissue type={level};sourcepath={v.file};linenumber={v.line};columnnumber={v.column};code={v.rule}]{v.message}'
        lines.append(line)
    return '\n'.join(lines)


def format_sarif(violations: List[Violation]) -> str:
    """Format as SARIF output"""
    rules = {}
    results = []

    for v in violations:
        if v.rule not in rules:
            rules[v.rule] = {
                'id': v.rule,
                'name': v.rule,
                'shortDescription': {'text': f'Markdown rule {v.rule}'},
                'fullDescription': {'text': f'Markdown linting rule {v.rule}'},
            }

        result = {
            'ruleId': v.rule,
            'level': 'error' if v.severity == 'error' else 'warning',
            'message': {'text': v.message},
            'locations': [{
                'physicalLocation': {
                    'artifactLocation': {'uri': v.file},
                    'region': {
                        'startLine': v.line,
                        'startColumn': v.column,
                    },
                },
            }],
        }
        results.append(result)

    sarif = {
        '$schema': 'https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json',
        'version': '2.1.0',
        'runs': [{
            'tool': {
                'driver': {
                    'name': 'rumdl',
                    'version': VERSION,
                    'informationUri': 'https://github.com/rvben/rumdl',
                    'rules': list(rules.values()),
                },
            },
            'results': results,
        }],
    }
    return json.dumps(sarif, indent=2)


def format_junit(violations: List[Violation], elapsed_ms: float = 0) -> str:
    """Format as JUnit XML"""
    # Group by file
    by_file = {}
    for v in violations:
        if v.file not in by_file:
            by_file[v.file] = []
        by_file[v.file].append(v)

    total_tests = len(by_file)
    total_failures = len(violations)
    total_time = elapsed_ms / 1000.0

    lines = ['<?xml version="1.0" encoding="UTF-8"?>']
    lines.append(f'<testsuites name="rumdl" tests="{total_tests}" failures="{total_failures}" errors="0" time="{total_time:.3f}">')

