                'fullDescription': {'text': f'Markdown linting rule {v.rule}'},
            }

        result = {
            'ruleId': v.rule,
            'level': 'error' if v.severity == 'error' else 'warning',
            'message': {'text': v.message},
            'locations': [{
                'physicalLocation': {
                    'artifactLocation': {'uri': v.file},
                    'region': {
                        'startLine': v.line,
                        'startColumn': v.column,
                    },
                },
            }],
        }
        results.append(result)

    sarif = {
        '$schema': 'https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json',
        'version': '2.1.0',
        'runs': [{
            'tool': {
                'driver': {
                    'name': 'rumdl',
                    'version': VERSION,
                    'informationUri': 'https://github.com/rvben/rumdl',
                    'rules': list(rules.values()),
                },
            },
            'results': results,
        }],
    }
    return json.dumps(sarif, indent=2)


def format_junit(violations: List[Violation], elapsed_ms: float = 0) -> str:
    """Format as JUnit XML"""
    # Group by file
    by_file = {}
    for v in violations:
        if v.file not in by_file:
            by_file[v.file] = []
        by_file[v.file].append(v)

    total_tests = len(by_file)
    total_failures = len(violations)
    total_time = elapsed_ms / 1000.0

    lines = ['<?xml version="1.0" encoding="UTF-8"?>']
    lines.append(f'<testsuites name="rumdl" tests="{total_tests}" failures="{total_failures}" errors="0" time="{total_time:.3f}">')

    for filepath, file_violations in by_file.items():
        suite_time = total_time / max(len(by_file), 1)
        lines.append(f'  <testsuite name="{filepath}" tests="1" failures="{len(file_violations)}" errors="0" time="{suite_time:.3f}">')
        lines.append(f'    <testcase name="Lint {filepath}" classname="rumdl" time="{suite_time:.3f}">')
        for v in file_violations:
            msg = v.message.replace("'", '&apos;').replace('"', '&quot;').replace('<', '&lt;').replace('>', '&gt;').replace('&', '&amp;')
            lines.append(f'      <failure type="{v.rule}" message="{msg}">{msg} at line {v.line}, column {v.column}</failure>')
        lines.append('    </testcase>')
        lines.append('  </testsuite>')

    lines.append('</testsuites>')
    return '\n'.join(lines)


