def run_check_command(args, remaining, config, is_fmt=False):
    """Run the check/fmt command"""
    start_time = time.time()

    no_config = getattr(args, 'no_config', False) or getattr(args, 'isolated', False)

    # Override config with CLI args
    if hasattr(args, 'config') and args.config:
        config = load_config(args.config, no_config)

    # Determine fix mode
    fix = is_fmt or getattr(args, 'fix', False)
    diff = getattr(args, 'diff', False)
    check_mode = getattr(args, 'check', False)

    # Determine output format
    output_format = 'text'
    if hasattr(args, 'output_format') and args.output_format:
        output_format = args.output_format
    elif hasattr(args, 'output') and args.output and args.output != 'text':
        output_format = args.output

    # Check for env var
    env_format = os.environ.get('RUMDL_OUTPUT_FORMAT', '')
    if env_format and output_format == 'text':
        output_format = env_format

    verbose = getattr(args, 'verbose', False)
    quiet = getattr(args, 'quiet', False)
    silent = getattr(args, 'silent', False)
    show_full_path = getattr(args, 'show_full_path', False)
    statistics = getattr(args, 'statistics', False)
    output_to_stderr = getattr(args, 'stderr', False)
    fail_on = getattr(args, 'fail_on', 'any')

    # Determine enabled rules
    enabled_rules = None

    if hasattr(args, 'enable') and args.enable:
        rules_list = [r.strip().upper() for r in args.enable.replace(',', ' ').split()]
        # Normalize
        rules_list = [normalize_rule_name(r) or r for r in rules_list]
        config.enable = rules_list

    if hasattr(args, 'disable') and args.disable:
        rules_list = [r.strip().upper() for r in args.disable.replace(',', ' ').split()]
        rules_list = [normalize_rule_name(r) or r for r in rules_list]
        config.disable = rules_list

    if hasattr(args, 'extend_enable') and args.extend_enable:
        rules_list = [r.strip().upper() for r in args.extend_enable.replace(',', ' ').split()]
        rules_list = [normalize_rule_name(r) or r for r in rules_list]
        config.enable = list(set(config.enable + rules_list))

    if hasattr(args, 'extend_disable') and args.extend_disable:
        rules_list = [r.strip().upper() for r in args.extend_disable.replace(',', ' ').split()]
        rules_list = [normalize_rule_name(r) or r for r in rules_list]
        config.disable = list(set(config.disable + rules_list))

    if hasattr(args, 'no_exclude') and args.no_exclude:
        config.exclude = []

    if hasattr(args, 'exclude') and args.exclude:
        patterns = [p.strip() for p in args.exclude.replace(',', ' ').split()]
        config.exclude.extend(patterns)

    if hasattr(args, 'include') and args.include:
        patterns = [p.strip() for p in args.include.replace(',', ' ').split()]
        config.include.extend(patterns)

    # Create linter
    linter = MarkdownLinter(config)

    if verbose and not silent:
        # Print enabled rules
        out = sys.stderr if output_to_stderr else sys.stdout
        print("Enabled rules:", file=out)
        for rule in sorted(linter.enabled_rules):
            desc = RULE_DESCRIPTIONS.get(rule, rule)
            print(f"  - {rule} ({desc})", file=out)
        print(f"\nExclude patterns: {config.exclude}", file=out)

    # Determine paths
    paths = getattr(args, 'paths', []) or []
    stdin_mode = getattr(args, 'stdin', False)

    if '-' in paths or stdin_mode:
        # Read from stdin
        stdin_filename = getattr(args, 'stdin_filename', None) or '<stdin>'
        content = sys.stdin.read()

        violations = linter.lint_file(stdin_filename, content)

        elapsed = (time.time() - start_time) * 1000

        out = sys.stderr if output_to_stderr else sys.stdout

        if fix or is_fmt:
            # Fix mode: output fixed content to stdout
            fixed = apply_all_fixes(content, violations)
            sys.stdout.write(fixed)
            return

        if violations:
            formatted = format_violations(violations, output_format, show_full_path)
            print(formatted, file=out)

            if not quiet and not silent:
                print(f"\nFound {len(violations)} issue(s) in {stdin_filename}", file=out)

            should_fail = check_fail(violations, fail_on)
            if should_fail:
                sys.exit(1)
        else:
            if not quiet and not silent:
                pass  # No output for success with stdin

        return

    if not paths and not remaining:
        paths = ['.']
    elif not paths:
        paths = remaining

    # Find markdown files
    files = find_markdown_files(paths, config)

    if not files:
        print("No markdown files found to check.", file=sys.stdout)
        sys.exit(1)

    out = sys.stderr if output_to_stderr else sys.stdout

    if verbose and not silent:
        for f in files:
            print(f"Processing file: {f}", file=sys.stderr)

    all_violations = []
    files_with_violations = []
    fixed_counts = {}

    for filepath in files:
        rel_path = os.path.relpath(filepath) if not show_full_path else os.path.abspath(filepath)
        if filepath == '<stdin>':
            rel_path = '<stdin>'

        violations = linter.lint_file(filepath)
        # Update filepath in violations
        for v in violations:
            v.file = rel_path

        if fix or is_fmt or diff or check_mode:
            try:
                with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
                    original = f.read()
            except Exception:
                continue

            # Apply fixes
            fixed_violations = [v for v in violations if v.fixable]
            unfixed_violations = [v for v in violations if not v.fixable]

            if diff or check_mode:
                # Show diff
                fixed_content = apply_all_fixes(original, violations)
                if fixed_content != original:
                    if diff:
                        show_diff(rel_path, original, fixed_content, out)
                    elif check_mode:
                        show_diff(rel_path, original, fixed_content, out)

                all_violations.extend(violations)
                if violations:
                    files_with_violations.append(filepath)
            else:
                fixed_content = apply_all_fixes(original, violations)

                if fixed_content != original:
                    with open(filepath, 'w', encoding='utf-8') as f:
                        f.write(fixed_content)

                # Re-check to see what's still unfixed
                remaining_violations = linter.lint_file(filepath)
                for v in remaining_violations:
                    v.file = rel_path

                # Show fix output
                for v in violations:
                    if v.fixable:
                        v_fixed = Violation(
                            file=v.file, line=v.line, column=v.column,
                            rule=v.rule, message=v.message, severity=v.severity,
                            fixable=True, fix_start=-1, fix_end=-1, fix_replacement=''
                        )
                        all_violations.append(v_fixed)
                    else:
                        all_violations.append(v)

                fixed_counts[filepath] = len(fixed_violations)
                if violations:
                    files_with_violations.append(filepath)
        else:
            all_violations.extend(violations)
            if violations:
                files_with_violations.append(filepath)

    elapsed = (time.time() - start_time) * 1000
    elapsed_str = f"{int(elapsed)}ms"

    # Format and print violations
    if not silent:
        if output_format in ('json', 'sarif', 'gitlab', 'junit'):
            if output_format == 'json':
                print(format_json(all_violations), file=out)
            elif output_format == 'sarif':
                print(format_sarif(all_violations), file=out)
            elif output_format == 'gitlab':
                print(format_gitlab(all_violations), file=out)
            elif output_format == 'junit':
                print(format_junit(all_violations, elapsed), file=out)
        else:
            for v in all_violations:
                if fix or is_fmt:
                    if v.fixable:
                        suffix = ' [fixed]'
                    else:
                        suffix = ''
                else:
                    suffix = ' [*]' if v.fixable else ''

                if output_format == 'concise':
                    suffix = ''

                line = f'{v.file}:{v.line}:{v.column}: [{v.rule}] {v.message}{suffix}'

                if output_format == 'grouped':
                    pass  # Will be handled separately
                elif output_format == 'github':
                    level = 'error' if v.severity == 'error' else 'warning'
                    end_col = v.column + 3
                    line = f'::{level} file={v.file},line={v.line},col={v.column},endLine={v.line},endColumn={end_col},title={v.rule}::{v.message}'
                elif output_format == 'pylint':
                    line = f'{v.file}:{v.line}:{v.column}: [C{v.rule[2:]}] {v.message}'
                elif output_format == 'azure':
                    level = 'error' if v.severity == 'error' else 'warning'
                    line = f'##vso[task.logissue type={level};sourcepath={v.file};linenumber={v.line};columnnumber={v.column};code={v.rule}]{v.message}'
                elif output_format == 'json-lines':
                    item = {
                        'file': v.file, 'line': v.line, 'column': v.column,
                        'rule': v.rule, 'message': v.message, 'severity': v.severity,
                        'fixable': v.fixable,
                    }
                    line = json.dumps(item)

                print(line, file=out)

