def check_fail(violations: List[Violation], fail_on: str) -> bool:
    """Determine if we should fail based on violations and fail_on setting"""
    if fail_on == 'never':
        return False
    if fail_on == 'any' or fail_on is None:
        return len(violations) > 0
    if fail_on == 'warning':
        return any(v.severity in ('warning', 'error') for v in violations)
    if fail_on == 'error':
        return any(v.severity == 'error' for v in violations)
    return len(violations) > 0


def apply_all_fixes(content: str, violations: List[Violation]) -> str:
    """Apply all fixable violations to content"""
    if not violations:
        return content

    lines = content.split('\n')
    fixable = [v for v in violations if v.fixable]

    if not fixable:
        return content

    # Group violations by line
    by_line = {}
    for v in fixable:
        li = v.line - 1
        if li not in by_line:
            by_line[li] = []
        by_line[li].append(v)

    new_lines = list(lines)

    # Apply line-level fixes (these are stable since they don't change line count)
    lines_to_remove = set()
    for li in sorted(by_line.keys()):
        if li >= len(new_lines):
            continue
        line_viols = by_line[li]
        current_line = new_lines[li]
        for v in sorted(line_viols, key=lambda x: x.column, reverse=True):
            result = apply_line_fix(new_lines, li, v)
            if result is None:
                lines_to_remove.add(li)
            else:
                new_lines[li] = result

    # Remove lines marked for removal
    new_lines = [l for i, l in enumerate(new_lines) if i not in lines_to_remove]

    # Multi-line fixes: insertions
    insertions = {}  # line_idx -> {'before': count, 'after': count}

    md022_viols = [v for v in fixable if v.rule == 'MD022']
    md031_viols = [v for v in fixable if v.rule == 'MD031']
    md032_viols = [v for v in fixable if v.rule == 'MD032']
    md065_viols = [v for v in fixable if v.rule == 'MD065']
    md058_viols = [v for v in fixable if v.rule == 'MD058']
    md071_viols = [v for v in fixable if v.rule == 'MD071']

    for v in md022_viols:
        li = v.line - 1
        if li not in insertions:
            insertions[li] = {'before': 0, 'after': 0}
        if 'above' in v.message:
            insertions[li]['before'] += 1
        elif 'below' in v.message:
            insertions[li]['after'] += 1

    for v in md031_viols:
        li = v.line - 1
        if li not in insertions:
            insertions[li] = {'before': 0, 'after': 0}
        if 'before' in v.message:
            insertions[li]['before'] += 1
        elif 'after' in v.message:
            insertions[li]['after'] += 1

    for v in md032_viols:
        li = v.line - 1
        if li not in insertions:
            insertions[li] = {'before': 0, 'after': 0}
        if 'preceded' in v.message:
            insertions[li]['before'] += 1
        elif 'followed' in v.message:
            insertions[li]['after'] += 1

    for v in md065_viols:
        li = v.line - 1
        if li not in insertions:
            insertions[li] = {'before': 0, 'after': 0}
        if 'before' in v.message:
            insertions[li]['before'] += 1
        elif 'after' in v.message:
            insertions[li]['after'] += 1

    for v in md058_viols:
        li = v.line - 1
        if li not in insertions:
            insertions[li] = {'before': 0, 'after': 0}
        if 'preceded' in v.message:
            insertions[li]['before'] += 1
        elif 'followed' in v.message:
            insertions[li]['after'] += 1

    for v in md071_viols:
        li = v.line - 1
        if li not in insertions:
            insertions[li] = {'before': 0, 'after': 0}
        insertions[li]['after'] += 1

    # Apply insertions
    result_lines = []
    for i, line in enumerate(new_lines):
        ins = insertions.get(i, {})
        for _ in range(ins.get('before', 0)):
            result_lines.append('')
        result_lines.append(line)
        for _ in range(ins.get('after', 0)):
            result_lines.append('')

    result = '\n'.join(result_lines)

    # MD047: ensure file ends with newline
    md047_viols = [v for v in fixable if v.rule == 'MD047']
    if md047_viols:
        if not result.endswith('\n'):
            result += '\n'

    # MD012: remove extra consecutive blank lines
    md012_viols = [v for v in fixable if v.rule == 'MD012']
    if md012_viols:
        result = fix_multiple_blanks(result)

    return result


def fix_multiple_blanks(content: str) -> str:
    """Remove extra consecutive blank lines"""
    lines = content.split('\n')
    fixed = []
    consecutive = 0
    for line in lines:
        if line.strip() == '':
            consecutive += 1
            if consecutive <= 1:
                fixed.append(line)
        else:
            consecutive = 0
            fixed.append(line)
    # Remove trailing blank lines beyond one
    while len(fixed) > 1 and fixed[-1].strip() == '' and fixed[-2].strip() == '':
        fixed.pop()
    return '\n'.join(fixed)


def show_diff(filepath: str, original: str, fixed: str, out=sys.stdout):
    """Show a diff between original and fixed content"""
    orig_lines = original.splitlines(keepends=True)
    fixed_lines = fixed.splitlines(keepends=True)

    import difflib

    diff = list(difflib.unified_diff(orig_lines, fixed_lines, 
                                     fromfile=filepath, tofile=f'{filepath} (fixed)'))

    if diff:
        print(''.join(diff), file=out)


def print_statistics(violations: List[Violation], out=sys.stdout):
    """Print statistics summary"""
    from collections import Counter
    rule_counts = Counter(v.rule for v in violations)
    fixable_by_rule = Counter(v.rule for v in violations if v.fixable)

    total = len(violations)

    print('\nRule Violation Statistics:', file=out)
    print(f'{"Rule":<8} {"Violations":<12} {"Fixable":<8} {"Percentage"}', file=out)
    print('-' * 50, file=out)

    for rule, count in sorted(rule_counts.items(), key=lambda x: -x[1]):
        fixable = fixable_by_rule.get(rule, 0)
        pct = count / total * 100
        print(f'{rule:<8} {count:<12} {fixable:<8} {pct:>8.1f}%', file=out)

    print('-' * 50, file=out)
    total_fixable = len([v for v in violations if v.fixable])
    print(f'{"Total":<8} {total:<12} {total_fixable:<8} {"100.0%":>9}', file=out)


