def find_markdown_files_with_display(paths: List[str], config: Config,
                                      respect_gitignore: bool = True) -> List[Tuple[str, str]]:
    """Find markdown files and return (filepath, display_path) tuples"""
    files = []
    seen = set()

    gitignore_patterns = []
    if respect_gitignore and config.respect_gitignore:
        gitignore_patterns = load_gitignore_patterns()

    for path in paths:
        if path == '-':
            if '-' not in seen:
                files.append(('-', '-'))
                seen.add('-')
            continue

        p = Path(path)

        # Normalize display path
        if os.path.isabs(path):
            display_prefix = path
        else:
            # Remove leading ./
            display_prefix = path.lstrip('./')
            if path.startswith('./'):
                display_prefix = path[2:]
            elif path.startswith('../'):
                display_prefix = path
            else:
                display_prefix = path

        if p.is_file():
            real_path = str(p.resolve()) if os.path.isabs(path) else str(p)
            display = path if not os.path.isabs(path) else path
            # Normalize: remove leading ./
            if display.startswith('./'):
                display = display[2:]
            fkey = str(p.resolve())
            if fkey not in seen:
                files.append((str(p), display))
                seen.add(fkey)
        elif p.is_dir():
            for root, dirs, filenames in os.walk(str(p)):
                # Sort dirs for consistent ordering
                dirs.sort()

                # Filter excluded directories
                dirs_to_remove = []
                for d in dirs:
                    dir_path_rel = os.path.relpath(os.path.join(root, d), str(p))
                    if should_exclude(dir_path_rel, config.exclude, gitignore_patterns):
                        dirs_to_remove.append(d)
                    # Also check just the dir name
                    elif should_exclude(d, config.exclude, gitignore_patterns):
                        dirs_to_remove.append(d)
                for d in dirs_to_remove:
                    dirs.remove(d)

                for fname in sorted(filenames):
                    if fname.endswith('.md') or fname.endswith('.markdown'):
                        fpath = os.path.join(root, fname)
                        rel_path = os.path.relpath(fpath)  # relative to CWD
                        fkey = os.path.realpath(fpath)

                        if fkey in seen:
                            continue

                        # Check excludes
                        rel_from_search = os.path.relpath(fpath, str(p))
                        if should_exclude(rel_from_search, config.exclude, gitignore_patterns):
                            continue
                        if should_exclude(fname, config.exclude, gitignore_patterns):
                            continue

                        if config.include:
                            if not should_include(rel_from_search, config.include) and \
                               not should_include(fname, config.include):
                                continue

                        seen.add(fkey)
                        files.append((fpath, rel_path))

    return files

