    if is_l and not in_list:
        in_list = True
    elif is_blank_line(line) and in_list:
        j = i + 1
        while j < len(lines) and is_blank_line(lines[j]):
            j += 1
        if j < len(lines):
            next_is_l = bool(re.match(r'^\s*[-*+]\s+', lines[j]) or re.match(r'^\s*\d+[.)]\s+', lines[j]))
            next_is_cont = bool(re.match(r'^  +\S', lines[j]))
            if not next_is_l and not next_is_cont:
